edges = set()
for i in range(12):
    for offset in [1, 2]:
        u = i
        v = (i + offset) % 12
        if u > v:
            u, v = v, u
        edges.add((u, v))

print(f"Number of edges: {len(edges)}")
degrees = {i: 0 for i in range(12)}
for u, v in edges:
    degrees[u] += 1
    degrees[v] += 1

print(f"Degrees: {degrees}")
print(f"Edges: {sorted(list(edges))}")
